{"name":"mcp__tea_rags__semantic_search","schema":"
```ts
declare const tools: { mcp__tea_rags__semantic_search(args: {
  // Blame owner (git blame HEAD), exact name.
  author?: string;
  // function | class | interface | block
  chunkType?: string;
  // Raw collection; prefer project + path.
  collection?: string;
  // Any FILE committer in git log window; exact name.
  contributor?: string;
  // Omitted → preset default may drop docs.
  documentation?: "only" | "exclude" | "include";
  // Payload dot-paths to return (relativePath always kept); unmatched → fieldsWarning. Omitted → [relativePath,symbolId,startLine,endLine,content]; metaOnly → [relativePath,symbolId,startLine,endLine,signature]. Paths: tea-rags://guide/signals.
  fields?: Array<string>;
  // File extension(s): '.ts' or ['.ts', '.py'].
  fileExtension?: string | Array<string>;
  // Raw Qdrant filter (must/should/must_not) or { presets: "a,b" }. Omitted → preset default filter; {} clears. tea-rags://guide/overview. Presets: production, coreLogic, securityPaths, freshLegacyEdits, fragileSilo, panicZone, godMethods, hubs, deadCandidates, unstableCore, battleTested, abandonedHotspots.
  filter?: { [key: string]: unknown; } | { presets: string; };
  // true → full import lists (default: count).
  includeImports?: boolean;
  // fanIn above p95. File-level.
  isHub?: boolean;
  // fanOut 0, fanIn > 0. File-level.
  isLeaf?: boolean;
  // Filter by programming language
  language?: string;
  // 'file' ranks whole files (file payload, no content); also scopes level-aware filters. Default: preset's.
  level?: "chunk" | "file";
  // Maximum number of results (default: 10)
  limit?: number;
  // Last commit ≤ N days ago (0 = today).
  maxAgeDays?: number;
  // Drop content; payload = locator (path, symbolId, lines, signature); signals via fields. Default: false.
  metaOnly?: boolean;
  // Last commit ≥ N days ago; chunk level drops no-commit chunks.
  minAgeDays?: number;
  // Min commits (churn).
  minCommitCount?: number;
  // fanIn+fanOut. File-level.
  minConnectionCount?: number;
  // File: importers; chunk level: call sites.
  minFanIn?: number;
  // File: imports; chunk level: outgoing calls.
  minFanOut?: number;
  // fanOut/(fanIn+fanOut), 0-1. File-level.
  minInstability?: number;
  // Chunk PageRank, 0-1.
  minPageRank?: number;
  // Transitive importer files. File-level.
  minTransitiveImpact?: number;
  // File last commit on/after ISO date.
  modifiedAfter?: string;
  // File last commit on/before ISO date.
  modifiedBefore?: string;
  // Skip first N results (pagination). Default: 0.
  offset?: number;
  // Your working tree (cwd / worktree); pass WITH project.
  path?: string;
  // Glob on file path (picomatch), e.g. '**/workflow/**', 'src/**/*.ts'.
  pathPattern?: string;
  // Alias from list_projects/prime; pass every call.
  project?: string;
  // Query text, or up to 5 variants (array or 'a ||| b') fused in one call.
  query: string | Array<string>;
  // Top FILE committer in git log window (not blame); name or email.
  recentAuthor?: string;
  // Preset, or {custom: {<signal>: number}}; signals: tea-rags://guide/signals, presets: tea-rags://guide/presets.
  rerank?: "relevance" | "decomposition" | "documentationRelevance" | "godModule" | "bugHunt" | "techDebt" | "hotspots" | "codeReview" | "dangerous" | "onboarding" | "securityAudit" | "refactoring" | "ownership" | "recent" | "stable" | "proven" | "criticalMethod" | "hotMethod" | "godMethod" | "blastRadius" | "architecturalHub" | "entryPoint" | "criticalPath" | { custom: { [key: string]: number; }; };
  // migrations = Rails schema history (not current state), relevance-ranked. Default code.
  scope?: "code" | "migrations";
  // Partial symbolId match: 'Class' → all its methods.
  symbolId?: string;
  // Commit-message task ID, e.g. TD-1234, #567.
  taskId?: string;
  // Omitted → preset default may drop tests.
  testFile?: "only" | "exclude" | "include";
}): "}

