declare const tools: { mcp__tea_rags__find_symbol(args: {
  // Raw collection; prefer project + path.
  collection?: string;
  // Payload dot-paths to return (relativePath always kept); unmatched → fieldsWarning. Omitted → lean default per mode. Paths: tea-rags://guide/signals.
  fields?: Array<string>;
  // true → full import lists (default: count).
  includeImports?: boolean;
  // Filter by programming language (for disambiguation in polyglot codebases)
  language?: string;
  // Maximum number of results (default: 50)
  limit?: number;
  // Existence check. Drop content; payload = locator (path, symbolId, lines, signature); signals via fields.
  metaOnly?: boolean;
  // Skip first N results (pagination). Default: 0.
  offset?: number;
  // Your working tree (cwd / worktree); pass WITH project.
  path?: string;
  // Glob scoping symbol-mode lookup, e.g. '**/services/**'. Ignored with relativePath.
  pathPattern?: string;
  // Alias from list_projects/prime; pass every call.
  project?: string;
  // File → full text if small, else outline; doc → heading TOC. Directory → files, top-level symbols, subdirs. Excludes symbol.
  relativePath?: string;
  // Preset or {custom: {<signal>: number}} (tea-rags://guide/signals) — attaches rankingOverlay.
  rerank?: "relevance" | "decomposition" | "documentationRelevance" | "godModule" | "bugHunt" | "techDebt" | "hotspots" | "codeReview" | "dangerous" | "onboarding" | "securityAudit" | "refactoring" | "ownership" | "recent" | "stable" | "proven" | "criticalMethod" | "hotMethod" | "godMethod" | "blastRadius" | "architecturalHub" | "entryPoint" | "criticalPath" | { custom: { [key: string]: number; }; };
  // Symbol or symbolId: Class#method (instance), Class.method (static), fn. Partial ok. Excludes relativePath.
  symbol?: string;
  // 1-20 symbol ids or file paths; file ≤150 lines → full text within batch budget, else outline. Excludes symbol, relativePath.
  symbols?: Array<string>;
}): "}
